import { Component, Prop, h, Host, Element, Watch, ComponentInterface } from '@stencil/core';
import { Slot, type Slots } from '@src/framework/decorators';
import { AvatarPropShape, AvatarSize } from '../avatar';

const prefix = 'avatar-group';

/**
 * @slot default - Slot for the `ks-avatar` items displayed inside the group. The group uses these slotted avatars to calculate overflow and sync shared `size` and `shape` values.
 * @part base - The base container of the component.
 */
@Component({
  tag: 'ks-avatar-group',
  styleUrl: 'index.scss',
  shadow: true,
})
export class KsAvatarGroup implements ComponentInterface {
  ['ks-name'] = 'ks-avatar-group';

  @Element() el!: HTMLKsAvatarGroupElement;

  /** The maximum number of avatar components to display simultaneously in the avatar group. If the number of avatars exceeds this value, the remaining ones will be collapsed. */
  @Prop() max = 5;
  /** The total number of avatars this group represents. If provided, this value is used to calculate the surplus count when the number of displayed avatars (up to `max`) is less than `total`. If not provided, `total` defaults to the actual number of slotted `ks-avatar` child components. */
  @Prop() total?: number;
  /** The size of the avatar components in the avatar group. This is the same as the `size` property of the individual avatars and can be one of the following values: `"xs"`, `"sm"`, `"md"`, or `"lg"`. */
  @Prop() size: AvatarSize = 'md';
  /** The shape of the avatar components in the avatar group. This is the same as the `shape` property of the individual avatars and can be one of the following values: `"square"` or `"circle"`. */
  @Prop() shape: AvatarPropShape = 'circle';

  @Slot({
    slotname: '_default',
    filter: (node?: Node & Partial<Element>) => Boolean(node?.tagName?.toLowerCase().startsWith('ks-avatar')),
  })
  private defaultSlots?: Slots<HTMLKsAvatarElement>;

  componentWillLoad() {
    if (this.total === undefined) {
      this.total = this.defaultSlots?.length ?? 0;
    }

    this.maxWatcher(this.max);
    this.sizeWatcher(this.size);
    this.shapeWatcher(this.shape);
  }

  @Watch('max')
  maxWatcher(val: number) {
    this.defaultSlots?.forEach((item, index) => {
      if (index >= val) {
        item.setAttribute('style-hidden', '');
      } else {
        item.removeAttribute('style-hidden');
      }
    });
  }

  @Watch('size')
  sizeWatcher(val: AvatarSize) {
    this.defaultSlots?.forEach((item) => {
      item.size = val;
    });
  }

  @Watch('shape')
  shapeWatcher(val: AvatarPropShape) {
    this.defaultSlots?.forEach((item) => {
      item.shape = val;
    });
  }

  private handleChangeSlot = () => {
    this.maxWatcher(this.max);
  };

  get hiddenAvatarCount() {
    return (this.total || 0) - Math.min(this.max, this.defaultSlots?.length ?? 0);
  }

  render() {
    return (
      <Host class="KsAvatarGroup">
        <div part="base" class={prefix}>
          <slot onSlotchange={this.handleChangeSlot}></slot>
          {this.hiddenAvatarCount > 0 && (
            <ks-avatar
              class={`${prefix}__surplus avatar-host-group ${prefix}__surplus__${this.size}`}
              size={this.size}
              shape={this.shape}
            >
              +{this.hiddenAvatarCount}
            </ks-avatar>
          )}
        </div>
      </Host>
    );
  }
}
